   if(g.dripstoneDefinition()==2){var legacyPlan=DripstoneLayer.plan(bare,random.seed(),c[0],c[1],level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.BIOME).getOrThrow(Biomes.DRIPSTONE_CAVES),1);formationPairs.add(new blockbranch.cubic.TerrainProfile[]{bare.withDripstone(legacyPlan),p.withCaveBiomes(CaveBiomeLayer.NONE)});require(legacyPlan.definition()==1,"Explicit legacy planner remains definition1");for(int k=2;k<legacyPlan.placements().length;k+=3)require(legacyPlan.placements()[k]<4,"Legacy planner never emits chain kinds");}
   if(!malformedChainChecked&&g.dripstoneDefinition()==2){var parts=p.dripstone().placements();for(int i=2;i<parts.length;i+=3)if(parts[i]>=4){int[] shortened=new int[parts.length-3];System.arraycopy(parts,0,shortened,0,i-2);System.arraycopy(parts,i+1,shortened,i-2,parts.length-i-1);var broken=encoded.copy();broken.getCompoundOrEmpty("dripstone").putIntArray("placements",shortened);boolean bad=false;try{TerrainProfile.decode(broken,factory);}catch(RuntimeException expected){bad=true;}require(bad,"Incomplete native chain descriptor rejected");malformedChainChecked=true;break;}}
