 private static volatile Object formationSink;
 private static void formationTiming(List<blockbranch.cubic.TerrainProfile[]> pairs,Path directory)throws Exception{
  var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();long tid=Thread.currentThread().threadId();require(bean.isThreadAllocatedMemoryEnabled()&&bean.isCurrentThreadCpuTimeSupported(),"Fixed-work counters available");var rows=new ArrayList<Map<String,Object>>();
  var lists=new ArrayList<Set<Integer>>();for(var pair:pairs){var sections=new TreeSet<Integer>(pair[0].dripstone().sections());sections.addAll(pair[1].dripstone().sections());lists.add(sections);}
  var jit=java.lang.management.ManagementFactory.getCompilationMXBean();var collectors=java.lang.management.ManagementFactory.getGarbageCollectorMXBeans();
  for(int round=-3;round<5;round++)for(int order=0;order<2;order++){
   int arm=(round&1)==0?order:1-order;long cpu=bean.getCurrentThreadCpuTime(),bytes=bean.getThreadAllocatedBytes(tid),wall=System.nanoTime(),blocks=0,checksum=0,compilation=jit.getTotalCompilationTime(),gc=collectors.stream().mapToLong(b->b.getCollectionTime()).sum();
   for(int repeat=0;repeat<32;repeat++)for(int n=0;n<pairs.size();n++)for(int sy:lists.get(n)){var section=pairs.get(n)[arm].generate(sy);formationSink=section;blocks+=4096;checksum+=net.minecraft.world.level.block.Block.getId(section.getBlockState(0,0,0));}
   if(round>=0){var row=new LinkedHashMap<String,Object>();row.put("round",round);row.put("definition",arm+1);row.put("blocks",blocks);row.put("cpuNs",bean.getCurrentThreadCpuTime()-cpu);row.put("bytes",bean.getThreadAllocatedBytes(tid)-bytes);row.put("wallNs",System.nanoTime()-wall);row.put("checksum",checksum);row.put("compilationMs",jit.getTotalCompilationTime()-compilation);row.put("gcMs",collectors.stream().mapToLong(b->b.getCollectionTime()).sum()-gc);rows.add(row);}
  }
  formationSink=null;Files.writeString(directory.resolve("formation-fixed-cost.json"),new GsonBuilder().setPrettyPrinting().create().toJson(rows));
 }
 private static void verifyVanillaInteractions(ServerLevel level,BlockPos root){
  var old=new LinkedHashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();for(int dy=-6;dy<=1;dy++){var p=root.offset(0,dy,0);old.put(p,level.getBlockState(p));level.setBlock(p,Blocks.AIR.defaultBlockState(),2);}
  try{
   // QA-only candidate geometry: never emitted by generation or saved as a new definition.
   for(var direction:List.of(Direction.UP,Direction.DOWN))for(int length=2;length<=3;length++){
    for(int dy=-6;dy<=1;dy++)level.setBlock(root.offset(0,dy,0),Blocks.AIR.defaultBlockState(),2);
    var anchor=direction==Direction.DOWN?root:root.below(6);
    level.setBlock(anchor,Blocks.DRIPSTONE_BLOCK.defaultBlockState(),2);
    for(int part=1;part<=length;part++){
     var thickness=part==length?net.minecraft.world.level.block.state.properties.SpeleothemThickness.TIP:part==length-1?net.minecraft.world.level.block.state.properties.SpeleothemThickness.FRUSTUM:net.minecraft.world.level.block.state.properties.SpeleothemThickness.BASE;
     var state=Blocks.POINTED_DRIPSTONE.defaultBlockState().setValue(PointedDripstoneBlock.TIP_DIRECTION,direction).setValue(PointedDripstoneBlock.THICKNESS,thickness);
     level.setBlock(anchor.relative(direction,part),state,2);
    }
    for(int part=1;part<=length;part++){var pos=anchor.relative(direction,part);require(level.getBlockState(pos).canSurvive(level,pos),"Native short chain supports "+direction+" length="+length+" part="+part);}
    if(direction==Direction.DOWN){level.setBlock(anchor.above(),Blocks.WATER.defaultBlockState(),2);require(PointedDripstoneBlock.getCauldronFillFluidType(level,anchor.below(length))==net.minecraft.world.level.material.Fluids.WATER,"Native multi-block chain resolves supplied water");level.setBlock(anchor,Blocks.AIR.defaultBlockState(),3);var first=anchor.below();require(level.getBlockTicks().hasScheduledTick(first,Blocks.POINTED_DRIPSTONE),"Native chain root schedules falling");
     level.getBlockState(first).tick(level,first,net.minecraft.util.RandomSource.create(1L));var entities=level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new net.minecraft.world.phys.AABB(anchor.below(length)).inflate(6));require(entities.size()==length,"Entire unsupported native chain falls");entities.forEach(net.minecraft.world.entity.Entity::discard);}
   }
   for(int dy=-6;dy<=1;dy++)level.setBlock(root.offset(0,dy,0),Blocks.AIR.defaultBlockState(),2);
   Blockbranch.LOGGER.info("DRIPSTONE_CHAIN_CONTROLS_PASS lengths=2,3 directions=up,down generationChanged=false");
   var up=Blocks.POINTED_DRIPSTONE.defaultBlockState().setValue(PointedDripstoneBlock.TIP_DIRECTION,Direction.UP);var down=up.setValue(PointedDripstoneBlock.TIP_DIRECTION,Direction.DOWN);var tip=root.below();var cauldron=root.below(5);
   level.setBlock(root,Blocks.DRIPSTONE_BLOCK.defaultBlockState(),2);level.setBlock(root.above(),Blocks.WATER.defaultBlockState(),2);level.setBlock(tip,down,2);level.setBlock(cauldron,Blocks.CAULDRON.defaultBlockState(),2);
   require(PointedDripstoneBlock.getCauldronFillFluidType(level,tip)==net.minecraft.world.level.material.Fluids.WATER,"Vanilla fluid transfer recognizes water above root");PointedDripstoneBlock.maybeTransferFluid(down,level,tip,0f);require(level.getBlockTicks().hasScheduledTick(cauldron,Blocks.CAULDRON),"Native dripping schedules cauldron fill");level.getBlockState(cauldron).tick(level,cauldron,net.minecraft.util.RandomSource.create(1L));require(level.getBlockState(cauldron).is(Blocks.WATER_CAULDRON),"Vanilla cauldron receives water");
   var victim=net.minecraft.world.entity.EntityTypes.PIG.create(level,net.minecraft.world.entity.EntitySpawnReason.COMMAND);float health=victim.getHealth();((PointedDripstoneBlock)Blocks.POINTED_DRIPSTONE).fallOn(level,up,root,victim,4d);require(victim.getHealth()<health,"Vanilla upward tip applies native fall damage");victim.discard();
   level.setBlock(root,Blocks.AIR.defaultBlockState(),3);require(level.getBlockTicks().hasScheduledTick(tip,Blocks.POINTED_DRIPSTONE),"Breaking support schedules the native falling tick");down.tick(level,tip,net.minecraft.util.RandomSource.create(1L));var falling=level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new net.minecraft.world.phys.AABB(tip).inflate(2));require(!falling.isEmpty(),"Unsupported native stalactite becomes falling block");falling.forEach(net.minecraft.world.entity.Entity::discard);
  }finally{old.forEach((p,s)->level.setBlock(p,s,2));}
 }
